def color_2x2_blocks(grid):
    """Partition the shape into 2x2 blocks (each missing at most one corner); color each block by its missing corner: none->1, top-left->2, bottom-left->3, top-right->4, bottom-right->5."""
    shape = cells(grid)
    sols = block_decompositions(shape)
